$('#spBatch').onclick=function(){var ids=$$('[data-sp]:checked').map(function(x){return x.getAttribute('data-sp')});if(!ids.length)return toast('\u8BF7\u5148\u52FE\u9009','err');showModal('\u6279\u91CF\u64CD\u4F5C','<p>\u5DF2\u9009\u4E2D '+ids.length+' \u4E2A\u6E90\u3002</p><div class="row"><button class="btn-green-soft" id="batchOn">\u542F\u7528</button><button class="btn-green-soft" id="batchOff">\u7981\u7528</button><button class="btn-danger" id="batchDel">\u5220\u9664</button></div>',function(){return true},'\u5173\u95ED',true);function batchPatch(patch,del){return Promise.all(ids.map(function(id){return api('/sources/spider/patch',{method:'POST',body:del?{id:id,delete:true}:{id:id,patch:patch}})}))}$('#batchOn').onclick=function(){batchPatch({enabled:true}).then(function(){cfg.spiders.forEach(function(s){if(ids.indexOf(s.id)>=0)s.enabled=true});closeModal();renderSpiders();toast('\u5DF2\u542F\u7528','ok')}).catch(function(e){toast(e.message,'err')})};$('#batchOff').onclick=function(){batchPatch({enabled:false}).then(function(){cfg.spiders.forEach(function(s){if(ids.indexOf(s.id)>=0)s.enabled=false});closeModal();renderSpiders();toast('\u5DF2\u7981\u7528','ok')}).catch(function(e){toast(e.message,'err')})};$('#batchDel').onclick=function(){batchPatch(null,true).then(function(){cfg.spiders=(cfg.spiders||[]).filter(function(s){return ids.indexOf(s.id)<0});closeModal();renderSpiders();toast('\u5DF2\u5220\u9664','ok')}).catch(function(e){toast(e.message,'err')})}}

