function openSubLink(s){api('/subscribe',{method:'POST',body:{subId:s.id,token:s.token||'',baseUrl:location.origin}}).then(function(j){var u=j.data.url;showModal('\u8BA2\u9605\u94FE\u63A5 \xB7 '+s.name,'<div class="linkbox" id="subLinkUrl">'+qs(u)+'</div><div class="row" style="margin-top:10px;gap:8px"><button class="btn" id="copySubLink">\u590D\u5236\u94FE\u63A5</button><span class="muted">\u94FE\u63A5\u53EA\u4E0E\u8BA2\u9605ID+\u4EE4\u724C\u7ED1\u5B9A\uFF0C\u589E\u5220\u6E90\u4E0D\u4F1A\u6539\u53D8\u94FE\u63A5</span></div>',function(){return true},'\u5173\u95ED',true);$('#copySubLink').onclick=function(){copyText(u);toast('\u94FE\u63A5\u5DF2\u590D\u5236','ok')};$('#modalOk').onclick=closeModal}).catch(function(e){toast(e.message,'err')})}
function loadSubs(){Promise.all([api('/app-data'),api('/sources?lite=1')]).then(function(r){appData=r[0].data||appData;cfg=r[1].data||cfg;renderSubs()}).catch(function(e){toast(e.message,'err')})}
function renderSubs(){var kw=($('#subSearch').value||'').toLowerCase();var list=(appData.subscriptions||[]).filter(function(s){return !kw||String(s.name||'').toLowerCase().indexOf(kw)>=0});$('#subBody').innerHTML=list.length?list.map(function(s){return '<tr><td><b>'+qs(s.name)+'</b><br><span class="muted">'+qs(s.desc||'')+'</span></td><td><span class="pill blue">'+qs(String(s.token||'').slice(0,12))+'\u2026</span></td><td>'+((s.spiders||[]).length)+' \u722C\u866B / '+((s.netdisk||[]).length)+' \u7F51\u76D8</td><td>'+(s.enabled!==false?'<span class="pill">\u542F\u7528</span>':'<span class="pill gray">\u7981\u7528</span>')+'</td><td><button class="btn-light btn-sm" data-sub-edit="'+qs(s.id)+'">\u7F16\u8F91</button> <button class="btn-green-soft btn-sm" data-sub-link="'+qs(s.id)+'">\u67E5\u770B\u94FE\u63A5</button> <button class="btn-danger btn-sm" data-sub-del="'+qs(s.id)+'">\u5220\u9664</button></td></tr>'}).join(''):'<tr><td colspan="5" class="loading">\u6682\u65E0\u8BA2\u9605</td></tr>';$$('[data-sub-edit]').forEach(function(b){b.onclick=function(){var s=(appData.subscriptions||[]).find(function(x){return x.id===b.getAttribute('data-sub-edit')});subModal(s)}});$$('[data-sub-del]').forEach(function(b){b.onclick=function(){var id=b.getAttribute('data-sub-del');var list=(appData.subscriptions||[]).filter(function(x){return x.id!==id});saveSection('subscriptions',list).then(function(){renderSubs();toast('\u5DF2\u5220\u9664','ok')})}});$$('[data-sub-link]').forEach(function(b){b.onclick=function(){var s=(appData.subscriptions||[]).find(function(x){return x.id===b.getAttribute('data-sub-link')});if(s)openSubLink(s)}})}
function subModal(s){s=s||{};var selected=(s.spiders||[]).slice(),netdisk=(s.netdisk||[]).slice();var options=(cfg.spiders||[]).map(function(x){return {id:x.id,name:x.name,type:x.type||'JavaScript'}});function syncNet(){$$('#modalBody [data-net]').forEach(function(x){var id=x.getAttribute('data-net');if(x.checked){if(netdisk.indexOf(id)<0)netdisk.push(id)}else{netdisk=netdisk.filter(function(v){return v!==id})}})}function html(d){d=d||{};var avail=options.filter(function(x){return selected.indexOf(x.id)<0});var chosen=selected.map(function(id){return options.find(function(x){return x.id===id})||{id:id,name:id,type:'js'}});var nets=(cfg.netdisk||[]).map(function(x){return '<label style="display:inline-block;margin:3px 12px 3px 0"><input type="checkbox" data-net="'+qs(x.id)+'"'+(netdisk.indexOf(x.id)>=0?' checked':'')+'> '+qs(x.name)+'</label>'}).join('')||'<span class="muted">\u6682\u65E0\u7F51\u76D8\u6E90</span>';return '<div class="field"><label>\u8BA2\u9605\u540D\u79F0</label><input id="subName" value="'+qs(d.name!=null?d.name:(s.name||''))+'"></div><div class="field"><label>\u63CF\u8FF0</label><input id="subDesc" value="'+qs(d.desc!=null?d.desc:(s.desc||''))+'"></div><div class="field"><label>\u8BBF\u95EE\u4EE4\u724C</label><div class="row"><input id="subToken" class="grow" value="'+qs(d.token!=null?d.token:(s.token||randomToken()))+'"><button class="btn-light" id="genToken">\u751F\u6210</button></div></div><div class="field"><label>\u9009\u62E9\u722C\u866B\u6E90</label><div class="transfer"><select id="subAvail" multiple>'+avail.map(function(x){return '<option value="'+qs(x.id)+'">'+qs(x.name)+' ['+qs(x.type)+']</option>'}).join('')+'</select><div class="midbtns"><button class="btn-green-soft btn-sm" id="toRight">&gt;</button><button class="btn-light btn-sm" id="toLeft">&lt;</button></div><select id="subChosen" multiple>'+chosen.map(function(x){return '<option value="'+qs(x.id)+'">'+qs(x.name)+' ['+qs(x.type)+']</option>'}).join('')+'</select></div><div class="muted">\u5DF2\u9009\u62E9 '+selected.length+' \u4E2A\u722C\u866B\u6E90</div></div><div class="field"><label>\u7F51\u76D8\u6E90</label><div style="max-height:100px;overflow:auto;border:1px solid var(--line);border-radius:7px;padding:8px">'+nets+'</div></div>'}function collect(){syncNet();return {name:$('#subName')?$('#subName').value:'',desc:$('#subDesc')?$('#subDesc').value:'',token:$('#subToken')?$('#subToken').value:''}}showModal(s.id?'\u7F16\u8F91\u8BA2\u9605':'\u65B0\u5EFA\u8BA2\u9605',html(),function(){syncNet();var name=$('#subName').value.trim();if(!name)throw new Error('\u8BF7\u586B\u5199\u8BA2\u9605\u540D\u79F0');var list=(appData.subscriptions||[]).slice();var item={id:s.id||uid(),name:name,desc:$('#subDesc').value.trim(),token:$('#subToken').value.trim()||randomToken(),spiders:selected.slice(),netdisk:netdisk.slice(),enabled:s.enabled!==false};var idx=list.findIndex(function(x){return x.id===item.id});if(idx>=0)list[idx]=item;else list.push(item);return saveSection('subscriptions',list).then(function(){renderSubs();toast(s.id?'\u5DF2\u4FDD\u5B58':'\u5DF2\u521B\u5EFA\u5E76\u751F\u6210\u94FE\u63A5','ok');setTimeout(function(){openSubLink(item)},200);return true})},'\u4FDD\u5B58');function bind(){if(!$('#genToken'))return;$('#genToken').onclick=function(){$('#subToken').value=randomToken()};$('#toRight').onclick=function(){var d=collect();$$('#subAvail option:checked').forEach(function(o){if(selected.indexOf(o.value)<0)selected.push(o.value)});refresh(d)};$('#toLeft').onclick=function(){var d=collect();$$('#subChosen option:checked').forEach(function(o){selected=selected.filter(function(id){return id!==o.value})});refresh(d)}}function refresh(d){var body=$('#modalBody'),st=body.scrollTop;body.innerHTML=html(d);body.scrollTop=st;bind()}bind()}
